from datetime import datetime,timezone
from pathlib import Path
import subprocess,json,hashlib,os
os.environ['PATH']='/usr/local/bin:/usr/bin:/bin:'+os.environ.get('PATH','')
config=Path('/Users/alexy/src/sail-extensions-gates/stream-experiments-20260930/logging02.json')
assert hashlib.sha256(config.read_bytes()).hexdigest()=='520b244165096bd2bb17a45d22effe50210d8bcf4bca5e546364f273cba36ff0'
vm_code="\nfrom pathlib import Path\nimport subprocess,json\nfrom datetime import datetime,timezone\nr={'started_utc':datetime.now(timezone.utc).isoformat()}\ntry:\n r['boot_id']=Path('/proc/sys/kernel/random/boot_id').read_text().strip()\n r['uptime']=Path('/proc/uptime').read_text().strip()\n p=subprocess.run(['/usr/bin/dmesg'],text=True,capture_output=True,timeout=15)\n r.update(returncode=p.returncode,stdout=p.stdout,stderr=p.stderr)\n r['boot_id_after']=Path('/proc/sys/kernel/random/boot_id').read_text().strip()\nexcept subprocess.TimeoutExpired as e:\n r.update(error_type='TimeoutExpired',stdout=e.stdout.decode(errors='replace') if isinstance(e.stdout,bytes) else e.stdout,\n          stderr=e.stderr.decode(errors='replace') if isinstance(e.stderr,bytes) else e.stderr)\nexcept Exception as e:\n r.update(error_type=type(e).__name__,error=str(e))\nr['finished_utc']=datetime.now(timezone.utc).isoformat();print(json.dumps(r))\n"

r={'started_utc':datetime.now(timezone.utc).isoformat(),'snapshots':{}}
commands=[('physical_memory',['/usr/sbin/sysctl','hw.memsize'],3),
 ('swap',['/usr/sbin/sysctl','vm.swapusage'],3),('vm_stat',['/usr/bin/vm_stat'],3),
 ('processes',['/bin/ps','-axo','pid=,ppid=,rss=,comm='],5),
 ('docker_running',['/usr/local/bin/docker','--context','colima-sail-gate','ps','--no-trunc','--format','{{.ID}} {{.Names}}'],5),
 ('guest',['/usr/local/bin/colima','--profile','sail-gate','ssh','--','sudo','-n','/usr/bin/python3','-B','-c',vm_code],20)]
for name,command,timeout in commands:
 try:
  p=subprocess.run(command,text=True,capture_output=True,timeout=timeout)
  r['snapshots'][name]={'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
 except subprocess.TimeoutExpired as e:
  r['snapshots'][name]={'error_type':'TimeoutExpired','stdout':e.stdout.decode(errors='replace') if isinstance(e.stdout,bytes) else e.stdout,'stderr':e.stderr.decode(errors='replace') if isinstance(e.stderr,bytes) else e.stderr}
 except Exception as e:
  r['snapshots'][name]={'error_type':type(e).__name__,'error':str(e)}
r['finished_utc']=datetime.now(timezone.utc).isoformat();print(json.dumps(r))
